namespace CheckoutPricing.Domain;

public enum LoyaltyTier
{
    Bronze,
    Silver,
    Gold,
}
E
cat > src/CheckoutPricing.Domain/LoyaltyDiscount.cs <<'E'
namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int PayableCents(LoyaltyTier tier, int subtotalCents)
    {
        var points = Math.Min(BasePoints(tier) + BonusPoints(subtotalCents), CeilingPoints);
        var discountCents = subtotalCents * points / 100;
        return subtotalCents - discountCents;
    }

    private static int BasePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
    };

    private static int BonusPoints(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0,
    };
}
E
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public int For(string tier, int subtotalCents)
    {
        return LoyaltyDiscount.PayableCents(Enum.Parse<LoyaltyTier>(tier), subtotalCents);
    }
}
E
dotnet test --verbosity quiet 2>&1 | tail -8

